from book import Chapter
c=Chapter('08')
c.src('ORIGINAL',80)
c.src('R49188',2)
c.add('''一个人看见的东西，怎样变成另一个人能够使用的知识？我们不可能把自己的大脑整个搬给对方，只能通过语言、图像、动作和其他符号，把其中某些关系表达出来。接收者再根据自身已有的经验，尝试重建这些关系。

因此，表达既需要区分，也需要共同基础。一个词如果每次都指向不同事物，交流就很难积累；但一个词如果只能指向眼前这一件东西，不能进入新的组合，也很难表达不断增加的经验。语言的力量，恰恰在于有限的组成部分能够形成丰富的表达。''')
c.heading('先有一个名字，还是先完全知道它是什么')
c.src('R48523',0,replacements=[('是不是先对','可以先对'),('就像米田引理那样','从关系的角度'),('直到所有的调整，都能得到预期的结果，这时候我们就可以声称我们知道了这个对象的内部结构和外部关系','随着更多调整与观察符合预期，我们对其结构和关系的认识就得到更多支持'),('不知道我们是否可以为AI的底层架构，也添加类似的机制','我们是否也可以为 AI 的底层架构添加类似机制'),('也许这就是通用人工智能的底座呢？','使它成为智能系统持续探索的一部分？')])
c.add('''这个过程说明，命名不必等到全部知识完成以后才发生。我们可以先把一个能够重复识别的现象留下来，再逐渐增加对它的解释。后来发现原来的理解不够准确，也不必把过去的观察全部抹掉，而是说明哪些关系需要改变。

例如，研究者给一种新现象起了名字，其他人便能够围绕同一问题交换观察。名字本身没有证明理论，但它为合作提供了一个可以反复返回的位置。科学概念的成长，需要这样的稳定性，也需要容许其内容继续变化。''')
c.heading('共同知道，比把文件放在网上更进一步')
c.src('R48731',17,start='再比如人的社会组织中',replacements=[('再比如','在'),('能够形成强壮，更稳定和更复杂的社会结构','有可能形成更稳定、能够持续合作的结构'),('却只能形成简单的，脆弱的，暂时性的结构和平衡','往往使其他参与者难以形成稳定预期'),('基于公共知识（Public Knowledge，即大家都知道，并且大家都知道大家都知道，这种循环递归的知识）的博弈','当参与者不仅知道某项规则，而且知道彼此都知道这项规则时，围绕共同知识展开的互动'),('能够形成类似范畴论中态射的复合性的结果，从而博弈出更复杂的社会结构','就有了把一个行动的结果接到另一个行动上的更好条件'),('请从范畴论角度出发考察不同范畴和对象的特性，对其构造复杂结构能力的影响。','这使我关注共同知识怎样影响复杂合作的构造能力。')])
c.add('''可以想象，两个人准备共同搬一件很重的家具。两个人都知道要往左移动，还不够；他们还需要知道对方也准备往左，并且准备在什么时候一起发力。否则，一方已经行动，另一方还在等待，就可能互相妨碍。

更大的组织也是如此。把一份规则放到公共位置，只是让它可以被看见；谁实际看过，是否认可，采用的是哪一个版本，仍然需要另外表达。可访问的信息、个人知道的信息与彼此确认的共同知识，不能直接画上等号。新框架要做的，是让这些关系能够被清楚记录，从而减少靠猜测维持合作的负担。''')
c.src('R54886',3,replacements=[('所谓基于 Merkle DAG，就是','我设想，'),('所有的公共知识都','适合共同保存的公共知识'),('能够防篡改，能够精确记录所有的变动','能够检查内容是否与已知标识一致，并记录明确保存下来的变动'),('这样就保证了我说的那种公共知识的特性','这为逐步形成共同知识提供了基础'),('它对所有参与方，也就是知识的提供方和接收方，都是完全透明的，并且不会有伪造和篡改','知识的提供方和接收方能够核对自己面对的内容版本，再通过相应的沟通与确认形成共识')])
c.heading('为什么要把知识的身份与保存位置分开')
c.src('ORIGINAL',82,replacements=[('唯一标识符','内容标识符')])
c.src('R55716',1,replacements=[('保证其独一无二性的概率足够大，以至于可以使用该hash值作为该字符串的标识符','在合适的密码学哈希和编码规则下，可以成为核对该字符串内容的标识符'),('而hash值具备的不可逆性，使得其具有很好的安全性，还具有防止原字符串被篡改，因此可以作为数字签名来保证其可靠性','得到内容以后，可以重新计算哈希，检查它是否与预期一致；若要证明由谁发布，还需要身份认证或数字签名'),('再者其唯一性和均匀分布性，可以通过hash算法快速索引定位寻址，使其还能够作为该字符串的地址，用于快速搜索定位','内容标识还可以作为索引键，帮助系统查找由哪些位置提供相应内容'),('规模可以任意扩展，不受限制','能够分布到多个节点，但扩展能力仍取决于具体实现和资源')])
c.add('''普通网址首先告诉我们去哪里寻找；内容标识首先告诉我们要核对什么。同一份材料可以有多个保存位置，位置改变不必意味着内容身份改变；内容修改以后，则应形成一个新的标识，并把新旧版本的关系明确连起来。

这种安排特别适合知识积累。一个结论依赖某一版本的实验记录，后来记录有了修正，旧结论的依据仍然能够被检查；新的结论则可以指向新的材料。我们不必让一个不断被覆盖的地址，同时承担“永远同一份内容”和“随时更新”两种互相冲突的任务。

但是，哈希只回答内容核对的问题。错误的论证也能有稳定标识；没有被提供的内容，知道标识也未必能取到；私有资料更不会因为有哈希而自动公开。知识是否成立、谁有权访问、采用哪个版本，都要作为另外的关系来处理。''')
c.heading('从网页之间的连接，到知识内部的连接')
c.src('R55365',48,start='merkle框架，与internet/web互联网架构',end='而merkle框架，将这个社会网络中数据和代码节点以及节点的颗粒度，以及这些基本粒子之间的链接，细化到最基本的语义单元层级。',replacements=[('merkle框架，与internet/web互联网架构，确实有很多可类比的地方','Merkle 框架与互联网、Web 架构有值得比较的地方'),('而merkle框架，将','我希望 Merkle 框架进一步将'),('这些基本粒子','这些基本单元')])
c.add('''一篇网页可以引用另一篇网页，但引用往往还不够细。它究竟使用了哪一个定义、哪一个实验结果，反对的是哪个条件下的结论？如果只能把整个网页当成一个不可再分的块，后续的人仍然需要反复阅读和重新拆解。

把粒度细化，是为了使这些关系可以进入公共记忆。一个定义、一段推理、一个反例、一项功能，都可以有明确边界。它们既能参与不同文章和项目，又保留自己的来源。这样，不同作品就不必各自重建同一套底层知识。''')
c.src('R55365',0,start='而这这个生态中',end='我觉得咱们这个框架，有可能完成从分散的AI智能体，以及小规模的智能体网络，到覆盖全球的社会神经智能网络的跨越。',replacements=[('而这这个生态中，不再存在','在所设想的生态中，要逐步打通'),('能够以同样的机制进行访问和共享','能够在适当权限下，用共同机制访问和共享'),('可以自动的通过benchmark/profiling机制，快速迭代进化','可以通过性能测试与运行分析，在可比较的条件下持续改进'),('无需传统软件硬件生态中，以不同个人，公司，组织为主体，通过专利，保密闭源等方式，在信息不透明不对等的情况下低效竞争的方式来迭代进化','让迭代更多建立在公开的功能、条件与结果上，减少信息不透明造成的重复和阻碍'),('直到tcp/ip以及http协议的软硬件互联网协议出现，全球信息革命的序幕才真正拉开','共同协议与连接方式的发展，使分散设备能够进入更大范围的合作'),('咱们这个框架','这个框架')])
c.add('''这也是我把语言问题与社会组织问题放在一起的原因。共享的符号和可核对的关系，使个体经验能够进入共同构造；共同构造又使更多人获得能力，继续产生新的经验。文明的记忆，不应只是一座等待查询的资料仓库，而应当成为可以不断参与行动的知识体系。

要走向这个方向，可以先从最小的一个人开始：把一个人的讨论、作品、实践和修正，放进能够保留内容、来源与关系的结构里。''')
c.save({'reasoning':'编码与重建→命名未知→共同知道→内容身份与位置→知识细粒度关联→共同构造','examples':['给未知现象命名','一起搬家具','旧实验版本与新结论','网页与段落级依赖'],'objections':['文件公开即共同知识吗','哈希能证明事实吗','知道CID必然能下载吗','统一是否抹平不同表达'],'voice':'保留作者通信、命名、公共知识与Web细粒度化论述；修正哈希签名混同','status':'初校；生物语言优劣的无根据倍数未纳入正文，原材料保留'})
